// ─── File: SchedulerWorkerDemo.java ───
// Scheduler (WHEN) atomically moves SCHEDULED→QUEUED; workers (HOW) lease jobs,
// recover crashes via visibility timeout, retry with backoff+jitter→DLQ,
// honor cancellation, and spread hot buckets by hash(jobId)%N.
import java.util.*;
import java.util.logging.*;

public class SchedulerWorkerDemo {
    private static final Logger log = Logger.getLogger("SW");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JobQueue queue = new JobQueue(30_000, 5);
        Scheduler scheduler = new Scheduler(queue, 4);

        // Scheduler atomically moves due jobs SCHEDULED → QUEUED (with shard).
        scheduler.schedule(new Job("reminder:SAV2001", "REMINDER"));
        scheduler.schedule(new Job("settle-retry:TXN88", "SETTLE_RETRY"));
        scheduler.schedule(new Job("reminder:CUR3001", "REMINDER"));
        log.info("=== Scheduler enqueued due jobs (atomic SCHEDULED→QUEUED) ===");

        Worker worker = new Worker(queue, 200, true);

        // Normal processing.
        worker.pollAndProcess(false, false);   // reminder:SAV2001 succeeds

        // Crash simulation: worker leases a job then dies before ack → visibility timeout.
        log.info("=== Worker crash: job leased, worker dies, lease expires, re-delivered ===");
        Job leased = queue.claim();             // leased, invisible to others
        log.warning(() -> "Worker crashed while holding " + (leased != null ? leased.id() : "?"));
        queue.expireLeases(System.currentTimeMillis() + 31_000);  // time passes past lease
        worker.pollAndProcess(false, false);    // another worker re-claims it

        // Failure + retry with backoff+jitter, then DLQ after max attempts.
        log.info("=== Failing job: retry backoff+jitter → dead-letter queue ===");
        scheduler.schedule(new Job("bad-job:X", "SETTLE_RETRY"));
        for (int i = 0; i < 6; i++) worker.pollAndProcess(true, false);  // always fails
        log.info(() -> "Dead-letter queue size: " + queue.deadLetterSize());

        // Cancellation honored by final state check before execute.
        log.info("=== Cancellation: queued job cancelled before execution is skipped ===");
        scheduler.schedule(new Job("reminder:CANCELME", "REMINDER"));
        queue.cancel("reminder:CANCELME");       // user cancels after it was queued
        worker.pollAndProcess(false, false);     // worker checks state → CANCELLED → skip
    }
}

// ─── model/Job.java ───
class Job {
    enum State { SCHEDULED, QUEUED, RUNNING, DONE, CANCELLED, DEAD }
    private final String id, type; private State state = State.SCHEDULED;
    private int attempts = 0; private long leaseUntil = 0; private int shard = 0;
    Job(String id, String type) { this.id = id; this.type = type; }
    String id() { return id; } String type() { return type; }
    State state() { return state; } void setState(State s) { state = s; }
    int attempts() { return attempts; } void incAttempts() { attempts++; }
    long leaseUntil() { return leaseUntil; } void setLeaseUntil(long t) { leaseUntil = t; }
    int shard() { return shard; } void setShard(int s) { shard = s; }
}

// ─── scheduler/Scheduler.java (atomic SCHEDULED→QUEUED + hot-bucket shard) ───
class Scheduler {
    private static final Logger log = Logger.getLogger("SW");
    private final JobQueue queue; private final int shards;
    Scheduler(JobQueue queue, int shards) { this.queue = queue; this.shards = shards; }
    void schedule(Job job) {
        // Hot-bucket spread: shard = hash(jobId) % N (same job → same shard always).
        int shard = Math.floorMod(job.id().hashCode(), shards);
        job.setShard(shard);
        // Atomic transition (in Redis: Lua ZREM+LPUSH; in SQL: UPDATE...+insert in one tx).
        job.setState(Job.State.QUEUED);
        queue.enqueue(job);
        log.info(() -> "SCHEDULED→QUEUED " + job.id() + " (shard " + shard + ")");
    }
}

// ─── queue/JobQueue.java (visibility timeout / lease + DLQ) ───
class JobQueue {
    private static final Logger log = Logger.getLogger("SW");
    private final Deque<Job> ready = new ArrayDeque<>();
    private final Map<String, Job> leased = new HashMap<>();   // invisible, awaiting ack
    private final Map<String, Job> dead = new HashMap<>();
    private final long visibilityMs; private final int maxAttempts;
    JobQueue(long visibilityMs, int maxAttempts) { this.visibilityMs = visibilityMs; this.maxAttempts = maxAttempts; }

    void enqueue(Job j) { ready.addLast(j); }

    // Claim = pull + lease (invisible for visibilityMs). Crash → lease expires → re-delivered.
    Job claim() {
        Job j = ready.pollFirst();
        if (j == null) return null;
        j.setLeaseUntil(System.currentTimeMillis() + visibilityMs);
        leased.put(j.id(), j);
        return j;
    }
    void ack(Job j) { leased.remove(j.id()); }          // done → remove for good
    void expireLeases(long nowMs) {
        List<String> expired = new ArrayList<>();
        for (Job j : leased.values()) if (j.leaseUntil() <= nowMs) expired.add(j.id());
        for (String id : expired) {
            Job j = leased.remove(id); ready.addLast(j);
            log.warning(() -> "Lease expired → re-delivering " + id);
        }
    }
    // Retry with backoff+jitter; after maxAttempts → dead-letter queue.
    void retryOrDeadLetter(Job j, long baseDelayMs, boolean jitter) {
        j.incAttempts();
        leased.remove(j.id());
        if (j.attempts() >= maxAttempts) {
            j.setState(Job.State.DEAD); dead.put(j.id(), j);
            log.severe(() -> j.id() + " exhausted " + maxAttempts + " attempts → DLQ");
            return;
        }
        long backoff = (long) (baseDelayMs * Math.pow(2, j.attempts()))
                + (jitter ? new Random().nextInt(100) : 0);
        log.warning(() -> "Retry " + j.id() + " attempt " + j.attempts() + " after " + backoff + "ms (backoff+jitter)");
        ready.addLast(j);
    }
    void cancel(String id) {
        for (Job j : ready) if (j.id().equals(id)) j.setState(Job.State.CANCELLED);
    }
    int deadLetterSize() { return dead.size(); }
}

// ─── worker/Worker.java (cancel check + retry) ───
class Worker {
    private static final Logger log = Logger.getLogger("SW");
    private final JobQueue queue; private final long baseDelayMs; private final boolean jitter;
    Worker(JobQueue queue, long baseDelayMs, boolean jitter) { this.queue = queue; this.baseDelayMs = baseDelayMs; this.jitter = jitter; }
    void pollAndProcess(boolean willFail, boolean unused) {
        Job j = queue.claim();
        if (j == null) return;
        // Cancellation: check authoritative state at the last moment before executing.
        if (j.state() == Job.State.CANCELLED) {
            log.info(() -> "Skipping cancelled job " + j.id());
            queue.ack(j); return;
        }
        j.setState(Job.State.RUNNING);
        try {
            if (willFail) throw new RuntimeException("downstream unavailable");
            j.setState(Job.State.DONE);
            log.info(() -> "DONE " + j.id());
            queue.ack(j);
        } catch (RuntimeException e) {
            log.log(Level.SEVERE, "Job " + j.id() + " failed", e);
            queue.retryOrDeadLetter(j, baseDelayMs, jitter);
        }
    }
}

